  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Kenneth J. Schafer",
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision picture and its quantum theory gave a remarkably powerful account of high-harmonic generation and opened attosecond science. It exposed new ways to study electron motion in atoms, with consequences well beyond a single technique.",
        "attribution": "Corkum's recollision model, Lewenstein's quantum formulation, and Schafer's early theoretical work are distinct, central contributions. The three-way credit is defensible, though the field grew through many experimental and theoretical contributions.",
        "maturity": "The framework has been tested across many systems and underpins decades of experiments, including attosecond pulse generation and measurement.",
        "uncertainties": [
          "The boundaries of credit among the foundational model, its quantum formulation, and subsequent experimental development are not perfectly sharp."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and made frequency comparisons sensitive probes of fundamental physics. This is a deep advance in measurement, not merely an improvement in a clock.",
        "attribution": "Katori and Ye made complementary foundational contributions to clock concepts and experimental realization. The two-person attribution is strong, while the broader precision-clock community also deserves recognition.",
        "maturity": "Independent groups have demonstrated exceptional accuracy and reproducibility, and the method has become a central platform for precision measurement.",
        "uncertainties": [
          "The most consequential future applications to tests of fundamental physics are still developing."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum information can, in principle, be protected, turning quantum computing from an abstract possibility into a physically meaningful program. Topological codes add a powerful and distinct organizing idea.",
        "attribution": "Shor and Steane independently established landmark quantum codes, while Kitaev's topological approach supplied a particularly influential framework. These contributions warrant recognition, though the overall development involved many researchers.",
        "maturity": "The principles have been experimentally demonstrated and increasingly used in quantum processors, but large-scale fault tolerance remains an active challenge.",
        "uncertainties": [
          "The ultimate practical reach of fault-tolerant quantum computing is not yet established."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "The theory and experiments behind trapped-ion and ultracold-atom quantum simulation made controlled many-body quantum systems accessible and created a new way to investigate quantum physics.",
        "attribution": "Cirac and Zoller supplied foundational theoretical proposals, and Blatt led landmark trapped-ion demonstrations. The candidate spans multiple platforms and a wider community, so a three-person attribution captures only a central part of the work.",
        "maturity": "The core ideas have been demonstrated repeatedly and have enabled increasingly sophisticated simulations, though the most ambitious applications remain under development.",
        "uncertainties": [
          "It is difficult to draw a clean boundary between this broad foundation and later quantum computing and simulation achievements."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B033",
      "proposed_laureates": [
        "Gerald Gabrielse",
        "Jeffrey Hangst",
        "Stefan Ulmer"
      ],
      "assessment": {
        "nobel_worthiness": "Trapping cold antimatter and comparing its properties with matter enables stringent tests of fundamental symmetries. The work joins precise atomic-scale measurement with a deep question about the structure of physical laws.",
        "attribution": "Gabrielse, Hangst, and Ulmer represent major contributions to antiproton and antihydrogen trapping and precision tests. The achievements are collaborative, and credit across experiments is necessarily broader.",
        "maturity": "Antimatter trapping is established, and precision measurements have advanced substantially, but many comparisons and tests continue to improve.",
        "uncertainties": [
          "The strongest possible constraints on CPT symmetry and related questions remain limited by evolving experimental precision."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Heino Falcke",
        "J. Anton Zensus",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Imaging the environment of a black hole at horizon scales was a striking observational achievement and a new test of gravity in an extreme regime.",
        "attribution": "Falcke's early imaging proposal, Zensus's leadership in very-long-baseline interferometry, and Doeleman's role in the observations form a plausible trio. The result depended on a very large collaboration, so individual credit is difficult to isolate.",
        "maturity": "The image has been followed by additional observations and independent analysis, but the observational record is still comparatively young.",
        "uncertainties": [
          "The extent to which the observations distinguish among models of black-hole environments and gravity continues to be assessed."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices turned ultracold atoms into a clean, tunable setting for studying quantum many-body physics, including phenomena that are difficult to access in solids.",
        "attribution": "Bloch, Greiner, and Esslinger led influential experimental advances, but the proposed attribution omits Zoller, whose theoretical work is central to the broader quantum-simulation foundation.",
        "maturity": "The platform is robust and widely used, with landmark phenomena reproduced and explored by many groups.",
        "uncertainties": [
          "The candidate overlaps substantially with broader quantum-simulation work, making the discovery boundary and laureate attribution less clear."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Maximilian Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Correcting spherical aberration made electron microscopy capable of resolving structures at much finer scales, a major advance in seeing and understanding matter.",
        "attribution": "Rose's theoretical and technical work and the experimental realization by Urban and Haider make a coherent trio, while other contributors to the instrument's development should also be acknowledged.",
        "maturity": "Aberration-corrected microscopes have been broadly adopted and have enabled extensive, reproducible scientific work.",
        "uncertainties": [
          "The scientific impact is clear, though the distinction between a transformative instrument advance and a fundamental physical discovery may affect prize priority."
        ]
      }
    }
  ]
}
